def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    t = int(data[0])
    aa = list(map(int, data[1:1+t]))

    flag = 0
    a, b = 1, 2
    for val in aa:
        if val == a:
            b = 6 - (a + b)
        elif val == b:
            a = 6 - (a + b)
        else:
            flag = 1
            break

    if flag == 1:
        print("NO")
    else:
        print("YES")

if __name__ == "__main__":
    solve()

